// Blob and File: parts, slices, streams, blobs backed by a file (fs.openAsBlob, which fail once the
// file changes) and blob: URLs. The same package under Node.js prints the same.
const fs = require("fs");
const os = require("os");
const path = require("path");
const { resolveObjectURL } = require("buffer");
module.exports = async function () {
  const b = new Blob(["héllo ", new Uint8Array([119, 111]), new Blob(["rld"])], { type: "Text/Plain" });
  console.log(b.size, b.type, await b.text());
  const s = b.slice(2, -2, "x/y");
  console.log(s.size, s.type, JSON.stringify(await s.text()), Buffer.from(await s.arrayBuffer()).toString("hex"));
  const chunks = [];
  for await (const c of b.stream()) chunks.push(c.length);
  console.log("stream", chunks, (await b.bytes()).length);
  const f = new File(["abc"], "a.txt", { type: "text/plain", lastModified: 5 });
  console.log(f.name, f.size, f.lastModified, await f.text(), f instanceof Blob);
  const p = path.join(os.tmpdir(), `blobtest-${process.pid}.bin`);
  fs.writeFileSync(p, Buffer.alloc(200000, 7));
  const fb = await fs.openAsBlob(p, { type: "application/octet-stream" });
  console.log("file", fb.size, fb.type, (await fb.arrayBuffer()).byteLength, (await fb.slice(199990).bytes()).join(","));
  let n = 0;
  for await (const c of fb.stream()) n += c.length;
  console.log("file stream", n);
  const r = new Response(fb.slice(0, 10));
  console.log("response", (await r.arrayBuffer()).byteLength, r.headers.get("content-type"));
  const url = URL.createObjectURL(b);
  console.log("url", url.startsWith("blob:nodedata:"), await resolveObjectURL(url).text());
  URL.revokeObjectURL(url);
  console.log("revoked", resolveObjectURL(url));
  fs.writeFileSync(p, "changed");
  try { await fb.text(); } catch (e) { console.log("changed", e.name, e.message); }
  fs.unlinkSync(p);
};
